import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { createNode as __unused } from '@/primitives';
import { createNode as __unused2 } from '@/text';

export default function createNode(config, ctx) {
  const {
    Group,
    Mesh,
    PlaneGeometry,
    SphereGeometry,
  } = ctx.THREE;

  // Root container – position/rotation/scale will be applied by the adapter.
  const root = new Group();

  // -------------------------------------------------------------------------
  // Card plane (textured)
  // -------------------------------------------------------------------------
  const PLANE_WIDTH = 1.6;   // aspect 512:320
  const PLANE_HEIGHT = 1.0;

  const planeGeometry = new PlaneGeometry(PLANE_WIDTH, PLANE_HEIGHT);
  const planeMaterial = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
    // map will be set asynchronously
  });

  const planeMesh = new Mesh(planeGeometry, planeMaterial);
  planeMesh.name = 'cardPlane';
  root.add(planeMesh);

  // Load texture (async, but creation stays synchronous)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      planeMaterial.map = tex;
      planeMaterial.needsUpdate = true;
    });
  }

  // -------------------------------------------------------------------------
  // Stock badge placeholder (will be bound to data externally)
  // -------------------------------------------------------------------------
  const badgeGeom = new SphereGeometry(0.05, 12, 12);
  const badgeMat = new MeshBasicNodeMaterial({ color: 0x00ff00, transparent: true });
  const badgeMesh = new Mesh(badgeGeom, badgeMat);
  badgeMesh.name = 'stockBadge';
  // Position badge at top‑right corner of the card
  badgeMesh.position.set(PLANE_WIDTH / 2 - 0.12, PLANE_HEIGHT / 2 - 0.12, 0.01);
  root.add(badgeMesh);
  // expose for external binding logic
  root.userData.stockBadge = badgeMesh;

  // -------------------------------------------------------------------------
  // Interaction handlers (hover lift & click press‑down + emit)
  // -------------------------------------------------------------------------
  const hoverTL = gsap.timeline({ paused: true });
  const originalY = root.position.y;
  hoverTL.to(root.position, {
    y: originalY + 0.15,
    duration: 0.5,
    ease: 'power3.out',
  });

  const clickTL = gsap.timeline({ paused: true });
  clickTL
    .to(root.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(4)',
    })
    .call(() => {
      ctx.emit('hub-journal.select', {});
    })
    .to(root.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.12,
      ease: 'back.out(4)',
    });

  // Store handlers on userData for the external system
  root.userData.handlers = {
    hover: () => hoverTL.play(),
    unhover: () => hoverTL.reverse(),
    click: () => clickTL.restart(),
  };

  // -------------------------------------------------------------------------
  // Cleanup routine
  // -------------------------------------------------------------------------
  root.userData.cleanup = () => {
    planeGeometry.dispose();
    planeMaterial.dispose();
    if (planeMaterial.map) planeMaterial.map.dispose();

    badgeGeom.dispose();
    badgeMat.dispose();

    hoverTL.kill();
    clickTL.kill();
  };

  return root;
}
